// oxlint-disable no-unused-vars -- the scoped specimen preserves hook ordering from its source
import { useState } from "react";
import { SectionPage, Specimen } from "../kit.js";
import { ChartLegend } from "../../ui/charts/index.js";

export default function ChartLegendExample() {
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  return (
    <SectionPage>
      <Specimen title="Toggle series with the pointer or keyboard">
        <ChartLegend
          items={[
            { key: "booked", label: "Booked", slot: 1, shape: "line" },
            { key: "available", label: "Available", slot: 2, shape: "line" },
          ]}
          hidden={hidden}
          onToggle={(key) =>
            setHidden((current) => {
              const next = new Set(current);
              if (next.has(key)) next.delete(key);
              else next.add(key);
              return next;
            })
          }
        />
      </Specimen>
    </SectionPage>
  );
}
